 "didYouKnow = (\n			| wisdom |\n			wisdom:: subject randomBitOfWisdom.\n			nil = wisdom actionLabel ifFalse: [ ^textAndActionWisdom: wisdom ].\n			nil = wisdom image ifFalse: [ ^textAndImageWisdom: wisdom ].\n			^textDisplay: wisdom text\n		)",
 "public isKindOfHomePresenter ^<Boolean> = (\n			^true\n		)",
 "navigateToNamespace = (\n			enterSubject:: NamespaceSubject new\n		)",
 "navigateToWorkspaces = (\n			enterSubject:: ide theWorkspaceManager AllWorkspacesSubject new\n		)",
 "navigateToRepositories = (\n			enterSubject:: ide repositories list\n		)",
 "textAndActionWisdom: wisdom = (\n			^column: {textDisplay: wisdom text. (link: wisdom actionLabel\n					action: wisdom actionBlock) smallFont. }\n		)",
 "textAndImageWisdom: wisdom = (\n			^row: {(image: wisdom image) height: styleButtonSize. mediumBlank. elastic: (textDisplay: wisdom text). }\n		)",
 "definition = (\n			^column: {helpSection. majorHeadingBlock: (row: {(label: 'Navigation') bold. filler. helpButton. dropDownMenu: [\n								actionsMenu\n							]. }). mediumBlank. indentedBlock: (column1: {link: 'Newspeak Source'\n							action: [ navigateToNamespace ]. }\n						column2: {link: 'Workspaces' action: [ navigateToWorkspaces ]. }\n						column3: {link: 'Repositories' action: [ navigateToRepositories ]. }). mediumBlank. \n				(* majorHeadingBlock: (label: 'Recently Visited' asText allBold).\n		mediumBlank.\n		indentedBlock:\n			(holder: [recentStuffDefinition]).\n		largeBlank. *)\n				majorHeadingBlock: (label: 'Did you know?') bold. mediumBlank. indentedBlock: (holder: [\n							didYouKnow\n						]). mediumBlank. indentedBlock: aboutSystemDefinition. }\n		)",
 "isMyKind: f <Fragment> ^<Boolean> = (\n			^f isKindOfHomePresenter\n		)",
 "public helpText ^<Fragment> = (\n			| mapping = Map new. |\n			mapping at: #hopscotchHelpButton put: helpButton;\n				at: #hopscotchMenu put: (dropDownMenu: [ actionsMenu ]).\n			^ampleforth: 'This is the IDE''s home page.<br><br>\nThe home page includes links to a variety of useful places, like the workspace manager, where you can evaluate code, and the IDE''s root namespace, which lists all top level classes and documents.<br> Directly above those links are the following widgets:\n<ul>\n<li><div class=\"hopscotchHelpButton\"> </div> The help button, which shows this help message.</li>\n<li><div class=\"hopscotchMenu\"> </div> The menu button. The only item in it is ''Inspect Presenter'' which will take you to an object inspector on this presenter (the home presenter). Inspect presenter is found in almost every menu; it lets you immediately find out what code is controlling the UI you are using at that point. It''s a great way to learn about the system.</li>\n</ul>\n'\n				mapping: mapping\n		)",
 "public class HomeSubject onModel: m\n	(* :exemplar: HomeSubject new *)\n	 = ProgrammingSubject onModel: m (\n		(* The Home screen is stateful.  The state is simply whether the\n    help text is displayed or not. *)\n		\n	)",
 "onModel: m",
 "onModel: m",
