 "public lexicallyLessOrEqual: a <String> than: b <String> ^<Boolean> = (\n			^outer Browsing lexicallyLessOrEqual: a than: b\n		)",
 "public uriForIconNamed: iconName <String> ^<String> = (\n			^(ide namespacing manifest Icons at: iconName) at: #src\n		)",
 "public isBinarySelector: s <String> ^<Boolean> = (\n			(* should do only called with selectors; not valid for arbitrary strings *)\n			\n			| firstChar = s runeAt: 1. |\n			\n			(* selector doesn't start with A-Z or a-z *)\n			^((65 <= firstChar and: [ 90 >= firstChar ]) or: [\n					97 <= firstChar and: [ 122 >= firstChar ]\n				]) not\n		)",
 "public isKeywordSelector: s <String> ^<Boolean> = (\n			(* should do only called with selectors; not valid for arbitrary strings *)\n			\n			^(s indexOf: ':') > 0\n		)",
 "public isUnarySelector: s <String> ^<Boolean> = (\n			(* should do only called with selectors; not valid for arbitrary strings *)\n			\n			^(isKeywordSelector: s) not and: [ (isBinarySelector: s) not ]\n		)",
 "public safelyRun: block <[]> ifFulfilled: successBlock <[:ThreadMirror | Object]> = (\n			safelyRun: block\n				ifFulfilled: successBlock\n				ifBroken: [ enterSubject:: ide debugging ThreadSubject onModel: thread ]\n		)",
 "public safelyRun: block <[]> ifFulfilled: successBlock <[:ThreadMirror | Object]> ifBroken: failBlock <[:ThreadMirror | Object]> = (\n			| thread <ThreadMirror> |\n			thread:: cachedPlatform mirrors ActivationMirror invokeSuspended: block.\n			thread resume.\n			thread isFulfilled ifTrue: [ successBlock value: thread ]\n				ifFalse: [ failBlock value: thread ]\n		)",
 "public safelyRun: block <[T def]> ^<T> = (\n			safelyRun: block ifFulfilled: [:thread | ^thread result ]\n		)",
 "public updateSubjects: subjectAccessor <[List[Subject]]> fromModel: modelAccessor <[List[Object]]> subjectFactory: subjectFactory <Subject class> = (\n			| subjectModels <List[Object]> = subjectAccessor value collect: [:e <Subject> |\n					e model\n				]. modelCollection <Collection[Object]> = modelAccessor value. obsoleteSubjects <List[Subject]> = List new. |\n			subjectAccessor value do: [:s <Subject> |\n					(modelCollection includes: s model) ifFalse: [ obsoleteSubjects add: s ]\n				].\n			obsoleteSubjects do: [:s <Subject> | subjectAccessor value remove: s ].\n			modelCollection do: [:m |\n					(subjectModels includes: m) ifFalse: [\n							subjectAccessor value add: (subjectFactory onModel: m)\n						]\n				]\n		)",
 "public isInstantiableUnarySelector: s <String> ^<Boolean> = (\n			^(isUnarySelector: s) and: [ s ~= #_cannotInstantiate ]\n		)",
 "public enterSubject: s = (\n			currentWindow enterSubject: s\n		)",
 "selectorsContinuingFrom: ws <List[String]> ^<List[Symbol]> = (\n			| w1 <String> = raiseCaseOf: ws first. wsRest = ws tail. cs = wsRest isEmpty ifFalse: [\n					selectorsContinuingFrom: wsRest\n				]\n				ifTrue: [\n					List new add: '';\n						yourself\n				]. ss = wsRest isEmpty ifFalse: [ selectorsStartingFrom: wsRest ]\n				ifTrue: [\n					List new add: '';\n						yourself\n				]. |\n			^List new addAll: (ss collect: [:s | w1 , ':' , s ]);\n				addAll: (cs collect: [:c | w1 , c ]);\n				yourself\n		)",
 "public computeSelectorsFrom: ws <Array[String]> ^<List[Symbol]> = (\n			| wordList = List withAll: ws. |\n			^(selectorsStartingFrom: wordList) select: [:s |\n					| lastColonIndex = s lastIndexOf: ':'. |\n					lastColonIndex = 0 or: [ lastColonIndex = s size ]\n				]\n		)",
 "public raiseCaseOf: selector <String> ^<String> = (\n			| selectorTail = selector size > 1 ifTrue: [\n					selector copyFrom: 2 to: selector size\n				]\n				ifFalse: [ '' ]. |\n			^(String with: selector first) asUppercase , selectorTail\n		)",
 "public implementedSubsetOf: selectors <Collection[Symbol]> ^<Collection[SelectorSubject]> = (\n			| selSubjects <Collection[SelectorSubject]> = selectors collect: [:each <Symbol> |\n					SelectorSubject onModel: each\n				]. |\n			^selSubjects select: [:selsub <SelectorSubject> |\n					selsub implementorList methodSubjects size > 0\n				]\n		)",
 "selectorsStartingFrom: ws <List[String]> ^<List[Symbol]> = (\n			| w1 <String> = ws first. u1 <String> = raiseCaseOf: w1. wsRest = ws tail. cs = wsRest isEmpty ifFalse: [\n					selectorsContinuingFrom: wsRest\n				]\n				ifTrue: [\n					List new add: '';\n						yourself\n				]. ss = wsRest isEmpty ifFalse: [ selectorsStartingFrom: wsRest ]\n				ifTrue: [\n					List new add: '';\n						yourself\n				]. |\n			^List new addAll: (ss collect: [:s | w1 , ':' , s ]);\n				addAll: (cs collect: [:c | w1 , c ]);\n				addAll: (ss collect: [:s | u1 , ':' , s ]);\n				addAll: (cs collect: [:c | u1 , c ]);\n				yourself\n		)",
