 "public binaryMsg ^<CombinatorialParser[MessageAST]> = (\n			^super binaryMsg wrapper: [:esend :b :e |\n					| args = {e. }. |\n					MessageAST new send: b value with: args;\n						isEventual: (nil = esend) not;\n						start: b start;\n						end: e end\n				]\n		)",
 "public binaryMsgPattern = (\n			^super binaryMsgPattern wrapper: [:sel :p |\n					| params |\n					params:: List new add: p;\n						yourself.\n					MessagePatternAST new selector: sel value parameters: params;\n						start: sel start;\n						end: p end\n				]\n		)",
 "public block ^<CombinatorialParser[BlockAST]> = (\n			^super block wrapper: [:lb :params :cb :rb |\n					| ps |\n					ps:: params isNil ifTrue: [ List new ] ifFalse: [ params ].\n					cb parameters: ps.\n					BlockAST new body: cb;\n						start: lb start;\n						end: rb end\n				]\n		)",
