 "public canUnderstand: selector <Symbol> ^<Boolean> = (\n			^methods includesMirrorNamed: selector\n		)",
 "find: name <String> in: aMixin <Mixin> ^<Mixin> = (\n			(* Defensive: when there is no existing mixin to look in (the\n	   enclosing MixinBuilder represents a brand-new class) — or no\n	   nested-class entry matching [name] in the runtime mixin — return\n	   nil rather than letting downstream code see a Mixin whose\n	   [runtimeMixin] is undefined (which then crashes [isMeta] etc.).\n	   Four cases handled:\n	     - [aMixin] is the Newspeak nil singleton (UndefinedObject)\n	     - [aMixin] is the JS [undefined] primitive\n	     - [aMixin.runtimeMixin] is undefined (e.g., an IntermediateMixin\n	       slipped in via a caller bug; see the prior\n	       IRBasedClassDeclarationBuilder>>computeInstanceSide issue)\n	     - [aMixin.runtimeMixin[manglePublicName]] is undefined (the\n	       nested-class slot doesn't exist in this mixin yet — a fresh\n	       nested class being added) *)\n			\n			| runtimeMixin nested |\n			nil = aMixin ifTrue: [ ^nil ].\n			(_js operator: '===' with: aMixin and: (_js ident: 'undefined')) ifTrue: [\n					^nil\n				].\n			runtimeMixin:: _js propertyOf: aMixin at: (_js literal: 'runtimeMixin').\n			(_js operator: '===' with: runtimeMixin and: (_js ident: 'undefined')) ifTrue: [\n					^nil\n				].\n			nested:: vmmirror ownPropertyOf: runtimeMixin\n				at: (compilation names manglePublic: name).\n			(_js operator: '===' with: nested and: (_js ident: 'undefined')) ifTrue: [\n					^nil\n				].\n			^Mixin fromRuntimeMixin: nested\n		)",
 "public isKindOfMixinMirror ^<Boolean> = (\n			^true\n		)",
 "public isMeta ^<Boolean> = (\n			^data isMeta\n		)",
 "nestedClassBuilderFor: nc <IntermediateClassDeclaration | ClassDeclarationMirror> within: em <Mixin> ^<ClassDeclartionBuilder> = (\n			data isKindOfIntermediateMixin ifTrue: [\n					^IRBasedClassDeclarationBuilder fromIR: nc\n						existingMixin: (find: nc qualifiedName in: em)\n						within: declaration\n				].\n			^MixinBasedClassDeclarationBuilder forExistingMixin: (find: nc qualifiedName\n					in: em)\n				within: declaration\n		)",
 "public reflecting: mxn <Mixin | ClassMixin> ^<MixinBuilder> = (\n			^mxn isMeta ifTrue: [\n					(ClassDeclarationBuilder reflecting: (MixinMirror reflecting: mxn) declaration instanceSide reflectee) classSide\n				]\n				ifFalse: [ (ClassDeclarationBuilder reflecting: mxn) instanceSide ]\n		)",
