 "public , otherSequence = (\n			^_js call: (_js propertyOf: self at: (_js literal: 'concat'))\n				with: {otherSequence asArray. }\n		)",
 "public asArray = (\n			^self\n		)",
 "public copy = (\n			(* A shallow copy, as on psoup. *)\n\n			^_js call: (_js propertyOf: (_js propertyOf: self\n						at: (_js literal: 'slice'))\n					at: (_js literal: 'call'))\n				with: {self. _js literal: 0. }\n		)",
 "public asOrderedCollection = (\n			^platform collections List withAll: self\n		)",
 "public at: index <Integer> ^<E> = (\n			| jsIndex |\n			(_js prefixOperator: 'typeof ' on: index) == 'number' ifFalse: [\n					^Error signal: 'ArgumentError'\n				].\n			jsIndex:: _js operator: '-' with: index and: (_js literal: 1).\n			(_js operator: '<' with: jsIndex and: (_js literal: 0)) ifTrue: [\n					^Error signal: 'ArgumentError'\n				].\n			(_js operator: '>=' with: jsIndex and: (_js verbatim: 'this.length')) ifTrue: [\n					^Error signal: 'ArgumentError'\n				].\n			^_js propertyOf: (_js ident: 'this') at: jsIndex\n		)",
 "public at: index <Integer> put: value <E> ^<E> = (\n			| jsIndex |\n			(_js prefixOperator: 'typeof ' on: index) == 'number' ifFalse: [\n					^Error signal: 'ArgumentError'\n				].\n			jsIndex:: _js operator: '-' with: index and: (_js literal: 1).\n			(_js operator: '<' with: jsIndex and: (_js literal: 0)) ifTrue: [\n					^Error signal: 'ArgumentError'\n				].\n			(_js operator: '>=' with: jsIndex and: (_js verbatim: 'this.length')) ifTrue: [\n					^Error signal: 'ArgumentError'\n				].\n			^_js assign: (_js propertyOf: (_js ident: 'this')\n					at: (_js operator: '-' with: index and: (_js literal: 1)))\n				toBe: value\n		)",
 "public binarySearchFor: el between: start and: end toCompare: compare = (\n			(* This does a binary search for the index such that if el was inserted before it\n	  the receiver would remain sorted.  The receiver must be sorted relative to the\n	  comparison block.  The comparison block should return true if the first block argument\n	  cannot appear after the second block argument *)\n			\n			| low high |\n			low:: start.\n			high:: end.\n			[ low <= high ] whileTrue: [\n					| mid |\n					mid:: low + high // 2.\n					(compare value: (self at: mid) value: el) ifTrue: [ low:: mid + 1 ]\n						ifFalse: [ high:: mid - 1 ]\n				].\n			^low\n		)",
 "public collect: block = (\n			(* Index loop, NOT native map: a block performing ^ returns the NLR sentinel (M4), which must propagate out of collect: -- map would store it as an ELEMENT and parsing-style NLR failure paths would corrupt the result instead of unwinding. *)\n			| i ::= 0. len ::= _js verbatim: 'this.length'. result r |\n			result:: _js new: (_js ident: 'Array') with: {len. }.\n			_js for: (_js verbatim: '')\n				while: (_js operator: '<' with: i and: len)\n				step: (_js postfixOperator: '++' on: i)\n				do: (_js block: {r:: _js call: block\n						with: {_js propertyOf: self at: i. }. _js if: (_js operator: '===' with: r and: (_js ident: 'NLRSentinel'))\n						then: (_js block: {_js return: r. }). _js assign: (_js propertyOf: result at: i)\n						toBe: r. }).\n			^result\n		)",
 "public copyFrom: start to: end = (\n			^_js call: (_js propertyOf: self at: (_js literal: 'slice'))\n				with: {start - 1. end. }\n		)",
 "public copyWith: extraElement = (\n			| newSize ::= self size + 1. a |\n			a:: (Array new: newSize) replaceFrom: 1 to: self size with: self.\n			a at: newSize put: extraElement.\n			^a\n		)",
 "public copyWithSize: s = (\n			^(Array new: s) replaceFrom: 1 to: (s min: self size) with: self\n		)",
 "defaultMedianOf: a <Int> and: b <Int> and: c <Int> ^<Int> = (\n			(* This is an untypesafe method that only works for MutableLists of elements that\n		have Magnitude relationships with each other.  It is used by the default sorting\n		method. *)\n			\n			| atA <E> atB <E> atC <E> |\n			atA:: at: a.\n			atB:: at: b.\n			atC:: at: c.\n			^atB <= atA ifFalse: [\n					atC <= atB ifFalse: [ b ]\n						ifTrue: [ atC <= atA ifFalse: [ c ] ifTrue: [ a ] ]\n				]\n				ifTrue: [\n					atB <= atC ifFalse: [ b ]\n						ifTrue: [ atA <= atC ifFalse: [ c ] ifTrue: [ a ] ]\n				]\n		)",
 "public defaultSort: l <Int> to: r <Int> = (\n			(* This is an untypesafe method that only works for MutableLists of elements that\n		have Magnitude relationships with each other *)\n			\n			| i <Int> j <Int> x <E> m <Int> n <Int> |\n			i:: l.\n			j:: r.\n			n:: r - l + 1.\n			n == 0 ifTrue: [ ^self ].\n			\n			(* Pick the partition value.  For <=7 elements, use the middle element.\n		For more than 7 but <= 40, use a median of three elements.  For > 40,\n		use a median of three medians of three *)\n			m:: l + r // 2.\n			n > 7 ifTrue: [\n					| pl <Int> pn <Int> s <Int> |\n					pl:: l.\n					pn:: r.\n					n > 40 ifTrue: [\n							s:: n // 8.\n							pl:: defaultMedianOf: pl and: pl + s and: pl + s + s.\n							m:: defaultMedianOf: m - s and: m and: m + s.\n							pn:: defaultMedianOf: pn - s - s and: pn - s and: pn\n						].\n					m:: defaultMedianOf: pl and: m and: pn\n				].\n			x:: at: m.\n			[ i <= j ] whileTrue: [\n					| ati <E> atj <E> |\n					[ x <= (ati:: at: i) ] whileFalse: [ i:: i + 1 ].\n					[ (atj:: at: j) <= x ] whileFalse: [ j:: j - 1 ].\n					i <= j ifTrue: [\n							at: i put: atj.\n							at: j put: ati.\n							i:: i + 1.\n							j:: j - 1\n						]\n				].\n			l < j ifTrue: [ defaultSort: l to: j ].\n			i < r ifTrue: [ defaultSort: i to: r ]\n		)",
 "public do: block = (\n			(* Index loop, NOT forEach: a block performing ^ returns the NLR sentinel (M4), which must break the loop and propagate out of do: -- native forEach would discard it and run every remaining element. *)\n			| i ::= 0. len ::= _js verbatim: 'this.length'. r |\n			_js for: (_js verbatim: '')\n				while: (_js operator: '<' with: i and: len)\n				step: (_js postfixOperator: '++' on: i)\n				do: (_js block: {r:: _js call: block\n						with: {_js propertyOf: self at: i. }. _js if: (_js operator: '===' with: r and: (_js ident: 'NLRSentinel'))\n						then: (_js block: {_js return: r. }). })\n		)",
 "public do: block separatedBy: betweenBlock = (\n			| firstTime ::= true. |\n			self do: [:element |\n					firstTime ifTrue: [ firstTime:: false ] ifFalse: [ betweenBlock value ].\n					block value: element\n				]\n		)",
 "public first = (\n			^self at: 1\n		)",
 "public flatMap: map <[:E | R def]> ^<Collection[R]> = (\n			^self flatten collect: map\n		)",
 "public flatten ^<Array> = (\n			| totalSize <Integer> ::= 0. c <Array> index <Integer> ::= 1. |\n			self do: [:e <E> |\n					totalSize:: totalSize + (e isKindOfCollection ifTrue: [ e size ]\n						ifFalse: [ 1 ])\n				].\n			c:: Array new: totalSize.\n			do: [:e <E> |\n					e isKindOfCollection ifTrue: [\n							e do: [:x |\n									c at: index put: x.\n									index:: index + 1\n								]\n						]\n						ifFalse: [\n							c at: index put: e.\n							index:: index + 1\n						]\n				].\n			^c\n		)",
 "public includes: element = (\n			self do: [:each | each = element ifTrue: [ ^true ] ].\n			^false\n		)",
 "public indexOf: element <E> ^<Integer> = (\n			1 to: self size do: [:index | (self at: index) = element ifTrue: [ ^index ] ].\n			^0\n		)",
 "public inject: initialValue into: accumulator = (\n			(* Index loop, NOT native reduce: propagate an NLR sentinel (M4) out of the fold instead of feeding it back as the accumulator. *)\n			| i ::= 0. len ::= _js verbatim: 'this.length'. acc |\n			acc:: initialValue.\n			_js for: (_js verbatim: '')\n				while: (_js operator: '<' with: i and: len)\n				step: (_js postfixOperator: '++' on: i)\n				do: (_js block: {acc:: _js call: accumulator\n						with: {acc. _js propertyOf: self at: i. }. _js if: (_js operator: '===' with: acc and: (_js ident: 'NLRSentinel'))\n						then: (_js block: {_js return: acc. }). }).\n			^acc\n		)",
