 "public testBooleanAsString = (\n			assert: true asString equals: 'true'.\n			assert: false asString equals: 'false'\n		)",
 "public testBooleanEvaluatingConjuction = (\n			assert: true & true.\n			deny: true & false.\n			deny: false & true.\n			deny: false & false\n		)",
 "public testBooleanEvaluatingDisjuction = (\n			assert: true | true.\n			assert: true | false.\n			assert: false | true.\n			deny: false | false\n		)",
