 "runningInPWA ^<Boolean> = (\n		^((js global at: #window) matchMedia: '(display-mode: minimal-ui)') at: #matches\n	)",
 "contentFor: menuItem <MenuItem | Symbol> within: dropDownContent ^<Alien[Element]> = (\n		| entry separator <Alien[Element]> |\n		menuItem = #separator ifTrue: [\n				separator:: document createElement: 'hr'.\n				(separator at: 'style') at: 'height' put: '1px';\n					at: 'background-color' put: styleBorderColor;\n					at: 'border' put: 'none';\n					at: 'margin-left' put: styleMenuInset;\n					at: 'margin-right' put: styleMenuInset.\n				^separator\n			].\n		entry:: document createElement: 'div'.\n		entry at: 'textContent' put: menuItem first.\n		(entry at: 'style') at: 'color' put: styleDefaultInterfaceTextColor;\n			at: 'font-family' put: styleFontFamilySansSerif;\n			at: 'font-size' put: styleFontSizeMenu;\n			at: 'padding-left' put: styleMenuInset;\n			at: 'padding-right' put: styleMenuInset;\n			at: 'height' put: styleMenuItemHeight;\n			at: 'line-height' put: styleMenuItemHeight;\n			at: 'white-space' put: 'nowrap'.\n		entry addEventListener: 'mouseover'\n			action: [:event |\n				(entry at: 'style') at: 'background-color' put: '#C8C8C8'.\n				nil\n			];\n			addEventListener: 'mouseout'\n				action: [:event |\n					(entry at: 'style') at: 'background-color' put: '#F6F6F6'.\n					nil\n				].\n		addMenuClickListener: menuItem to: entry.\n		^entry\n	)",
 "public blobURIFor: file <Alien[File]> ^<String> = (\n		^(window at: #URL) createObjectURL: file\n	)",
 "public onDrop: e <Alien[DragEvent]> do: blk <[:List[JSFile] :Point | Object]> = (\n		| files = (e at: #dataTransfer) at: #files. pos = Point x: (e at: #clientX)\n			y: (e at: #clientY). fs <List[JSFile]> = List new. |\n		0 to: (files at: #length) - 1 do: [:i <Integer> | fs add: (files at: i) ].\n		blk value: fs value: pos\n	)",
 "showMenu: menu <Alien[Div]> forShell: s <HopscotchShell> inVisual: v <Visual> = (\n		(* See showMenu:forFragment: -- portal the popup to <body> so a positioned /\n	   backdrop-filtered / overflow-clipped ancestor cannot clip it or trap its\n	   positioning, lift it above the app (z-index), then clamp it into the viewport\n	   so a trigger near an edge does not push part of the menu off-screen. *)\n		| vbr = v getBoundingClientRect. host <Alien[Node]> = document at: #body. |\n		host appendChild: menu.\n		(menu at: 'style') at: 'position' put: 'absolute';\n			at: 'width' put: (menu at: 'offsetWidth') asString , 'px';\n			at: 'z-index' put: '1000'.\n		positionMenu: menu atTriggerRect: vbr.\n		menu at: 'tabIndex' put: 0.\n		menu at: 'onblur'\n			put: [:event |\n				s closeActiveMenu.\n				nil\n			].\n		menu focus.\n		s activeMenu: menu.\n		s activeMenuParent: host\n	)",
 "showMenu: menu <Alien[Div]> forFragment: m <DropDownMenuFragment> = (\n		(* Portal the popup to <body> rather than nesting it inside the trigger. The\n	   trigger may sit inside a positioned / backdrop-filtered / overflow-clipped\n	   container (e.g. an OverlayComposer's control), any of which would clip the\n	   popup or trap its absolute positioning and saddle it with scrollbars. As a\n	   direct child of the static <body>, the popup's page-coordinate positioning\n	   (scroll + the trigger's client rect) resolves against the initial containing\n	   block -- exactly as it did for a trigger with no positioned ancestor.\n	   activeMenuParent tracks <body> so closeActiveMenu still removes it. *)\n		| s <HopscotchShell> = m shell. v <Visual> = m visual. vbr = v getBoundingClientRect.\n		host <Alien[Node]> = document at: #body. |\n		host appendChild: menu.\n		(menu at: 'style') at: 'position' put: 'absolute';\n			at: 'width' put: (menu at: 'offsetWidth') asString , 'px';\n\n			(* Above any positioned/filtered UI it may overlap -- notably an\n	     OverlayComposer control (z-index 30) sitting right where the popup opens.\n	     As a <body> child a high z-index makes it top-most across the app. *)\n			at: 'z-index' put: '1000'.\n		positionMenu: menu atTriggerRect: vbr.\n		menu at: 'tabIndex' put: 0.\n		menu at: 'onblur'\n			put: [:event |\n				m removeContentFromShell: s.\n				nil\n			].\n		menu focus.\n		s activeMenu: menu.\n		s activeMenuParent: host\n	)",
 "positionMenu: menu <Alien[Div]> atTriggerRect: vbr <Alien[DOMRect]> = (\n		(* Place the popup at the trigger's top-left (in page coordinates), but shifted\n	   just enough to stay inside the viewport when it would otherwise spill past the\n	   right or bottom edge -- e.g. a menu on a right-aligned top-level control whose\n	   trigger sits near the window edge. offsetWidth/Height are read after the popup\n	   is in the DOM and its width is fixed, so they are the real rendered size. *)\n		| margin <Integer> = 4. mw <Integer> = menu at: 'offsetWidth'. mh <Integer> = menu at: 'offsetHeight'.\n		vw <Integer> = window at: #innerWidth. vh <Integer> = window at: #innerHeight.\n		left ::= vbr at: 'left'. top ::= vbr at: 'top'. |\n		(left + mw) > vw ifTrue: [ left:: vw - mw - margin ].\n		left < margin ifTrue: [ left:: margin ].\n		(top + mh) > vh ifTrue: [ top:: vh - mh - margin ].\n		top < margin ifTrue: [ top:: margin ].\n		(menu at: 'style') at: 'left' put: ((window at: #scrollX) + left) asString , 'px';\n			at: 'top' put: ((window at: #scrollY) + top) asString , 'px'\n	)",
 "clearCurrentMenu = (\n		currentHopscotchWindow activeMenuBlurred\n	)",
 "addMenuClickListener: menuItem <MenuItem | Symbol> to: entry <Alien[HTMLElement]> = (\n		entry addEventListener: 'click'\n			action: [:event |\n				event stopPropagation.\n				currentHopscotchWindow activeMenuBlurred.\n				menuItem last value.\n				nil\n			]\n	)",
